-- Запись журнала обновлений (ADR 0077): выпуск 50 — машинист и техника меняются внутри срока
-- заказа, а неделя ЭСМ-2 режется по дню смены (ADR 0126).
--
-- Схему миграция не трогает — она только заводит запись выпуска, как 0126, 0128, 0134, 0135, 0140,
-- 0158, 0159, 0160, 0163, 0165, 0168, 0169, 0170, 0173, 0174, 0184, 0189, 0190, 0193 и 0196
-- (ADR 0077 §4). Схему этого выпуска меняли 0166 (таблица истории и состояние у заявки) и 0167
-- (управляющая строка режимов, аттестации, журнал переходов) — обе выкачены раньше.
--
-- Номер файла и `seq` взяты по факту на момент создания: на 25.08.2026 последняя миграция в дереве
-- — 0199, последний выпуск — 49 (0196, версия `0.1.42.0135`), отсюда файл 0200 и `seq = 50`.
-- Разойдись эта пара с очередью — накат упёрся бы в первичный ключ `app_releases`.
--
-- Хвост версии — номер ADR решения: работа описана ADR 0126, отсюда `0.1.43.0126`.
--
-- ЧЕГО В ПУНКТАХ НЕТ И ПОЧЕМУ. Ни слова про режимы чтения, теневое сравнение и переключение
-- источника истории: журнал читают диспетчер и бухгалтер, а не сопровождение. Для них выпуск — это
-- три новых окна и два листа на неделю вместо одного; всё остальное — устройство, и живёт оно в
-- runbook и в ADR. По той же причине здесь нет и разреза как термина: в пунктах он назван тем, чем
-- выглядит на экране, — сменой состава с названной даты.

INSERT INTO app_releases (seq, version, released_on, title, adrs, items) VALUES (
  50, '0.1.43.0126', '2026-08-25', 'Машинист и техника меняются внутри срока заказа', '{126}',
  '[
    {"kind":"feature","text":"У заказа спецтехники появилось окно «Сменить машиниста»: кто садится за технику и с какого числа. Прежний машинист работает по названный день включительно, а с даты смены выписывается новый лист ЭСМ-2 — отработанные дни не переписываются"},
    {"kind":"feature","text":"«Состав по датам» в том же окне показывает историю заказа отрезками: с какого числа какая машина и какой человек, кто и когда это решил. Решение, заведённое за концом срока, не прячется — у него своя строка «Ожидает продления срока» и кнопка отмены"},
    {"kind":"feature","text":"Появилось окно «Починка истории»: назвать машинистов на днях, где история их не знает, заполнить известным человеком закрытое прошлое и решить, какая машина работает после конца срока. Открывается из меню заказа, когда чинить есть что"},
    {"kind":"feature","text":"Перед каждым таким действием портал показывает его цену: какие бланки сгорят, какие выпишутся, какие отработанные листы придётся переоформить и снимется ли чья-то виза. Подтверждают именно показанное — если за время просмотра что-то изменилось, портал пересчитает и попросит прочитать заново"},
    {"kind":"improvement","text":"Неделя со сменой состава даёт два листа ЭСМ-2 — с разными людьми и своими днями. В сводке по путевым листам такая неделя показана двумя строками, а над таблицей стоит пояснение, почему их две"},
    {"kind":"improvement","text":"Срок работ правится отдельным окном, а не общей формой заказа: продление и сокращение показывают, что произойдёт с бумагой и с решениями о технике за новым концом срока"},
    {"kind":"improvement","text":"Дни, за которые история никого не знает, названы честно — «машинист неизвестен, историю восстановили по бланкам», а не пустой строкой. Пока такие дни есть, портал прямо говорит, чего ждёт от заказа"}
  ]'::jsonb
);
